import java.text.Normalizer;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The filters understood by the customer backend.
 *
 * <p>Name terms are normalized once when the filter is created. Customer names
 * are normalized in the same way when a query is evaluated, making substring
 * matching case- and accent-insensitive in both directions.
 */
public final class CustomerFilter {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
    private static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private final String name;
    private final Set<CustomerStatus> statuses;
    private final List<String> nameTerms;

    public CustomerFilter(String name, Set<CustomerStatus> statuses) {
        this.name = name == null ? "" : name;
        this.statuses = statuses == null || statuses.isEmpty()
                ? Set.of()
                : Set.copyOf(EnumSet.copyOf(statuses));

        String normalizedName = normalize(this.name).strip();
        this.nameTerms = normalizedName.isEmpty()
                ? List.of()
                : List.of(WHITESPACE.split(normalizedName));
    }

    public static CustomerFilter empty() {
        return EMPTY;
    }

    public String name() {
        return name;
    }

    public Set<CustomerStatus> statuses() {
        return statuses;
    }

    public boolean isEmpty() {
        return nameTerms.isEmpty() && statuses.isEmpty();
    }

    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }

        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return nameTerms.stream()
                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    private static String normalize(String value) {
        return DIACRITICS.matcher(Normalizer.normalize(value, Normalizer.Form.NFD))
                .replaceAll("")
                .toLowerCase(Locale.ROOT);
    }
}
